answer:
func lengthOfLongestSubstring(s string) int {
	last := make(map[byte]int)
	best, left := 0, 0
	for r := 0; r < len(s); r++ {
		if j, ok := last[s[r]]; ok && j >= left {
			left = j + 1
		}
		last[s[r]] = r
		if r-left+1 > best {
			best = r - left + 1
		}
	}
	return best
}

