import "testing"

func TestIsValidBST(t *testing.T) {
	valid := &TreeNode{Val: 2,
		Left:  &TreeNode{Val: 1},
		Right: &TreeNode{Val: 3}}
	if !isValidBST(valid) {
		t.Fatal("[2,1,3] should be a valid BST")
	}
	if !isValidBST(nil) {
		t.Fatal("empty tree should be a valid BST")
	}
	badChild := &TreeNode{Val: 5,
		Left:  &TreeNode{Val: 1},
		Right: &TreeNode{Val: 4, Left: &TreeNode{Val: 3}, Right: &TreeNode{Val: 6}}}
	if isValidBST(badChild) {
		t.Fatal("[5,1,4,null,null,3,6] is not a valid BST")
	}
	// Locally fine at every parent, but 4 sits in the left subtree of 5.
	deepViolation := &TreeNode{Val: 5,
		Left:  &TreeNode{Val: 3, Left: &TreeNode{Val: 2}, Right: &TreeNode{Val: 4}},
		Right: &TreeNode{Val: 8, Left: &TreeNode{Val: 4}, Right: &TreeNode{Val: 9}}}
	if isValidBST(deepViolation) {
		t.Fatal("a node violating an ancestor bound must be rejected")
	}
	if isValidBST(&TreeNode{Val: 1, Left: &TreeNode{Val: 1}}) {
		t.Fatal("equal values are not allowed in a strict BST")
	}
}

answer:
func isValidBST(root *TreeNode) bool {
	var check func(n *TreeNode, lo, hi *int) bool
	check = func(n *TreeNode, lo, hi *int) bool {
		if n == nil {
			return true
		}
		if lo != nil && n.Val <= *lo {
			return false
		}
		if hi != nil && n.Val >= *hi {
			return false
		}
		return check(n.Left, lo, &n.Val) && check(n.Right, &n.Val, hi)
	}
	return check(root, nil, nil)
}

