func merge(intervals [][]int) [][]int {
	sortByStart(intervals)
	out := [][]int{}
	for _, iv := range intervals {
		n := len(out)
		if n > 0 && iv[0] <= out[n-1][1] {
			if iv[1] > out[n-1][1] {
				out[n-1][1] = iv[1]
			}
			continue
		}
		out = append(out, []int{iv[0], iv[1]})
	}
	return out
}

